import{_ as i,H as a,f as e,i as t}from"./chunks/framework.BH2BK_3i.js";const m=JSON.parse('{"title":"02｜收拾行李，准备上路","description":"","frontmatter":{},"headers":[{"level":2,"title":"LLM 应用开发必备基础知识","slug":"llm-应用开发必备基础知识","link":"#llm-应用开发必备基础知识","children":[]},{"level":2,"title":"开源语言模型的发布平台和文件格式","slug":"开源语言模型的发布平台和文件格式","link":"#开源语言模型的发布平台和文件格式","children":[]},{"level":2,"title":"准备开发机器和系统","slug":"准备开发机器和系统","link":"#准备开发机器和系统","children":[]},{"level":2,"title":"开源 LLM 的部署工具——Ollama","slug":"开源-llm-的部署工具——ollama","link":"#开源-llm-的部署工具——ollama","children":[]},{"level":2,"title":"总结时刻","slug":"总结时刻","link":"#总结时刻","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"LLM自主智能体应用实战课/02｜收拾行李，准备上路.md","filePath":"LLM自主智能体应用实战课/02｜收拾行李，准备上路.md","lastUpdated":1779815961000}'),p={name:"LLM自主智能体应用实战课/02｜收拾行李，准备上路.md"};function n(r,l,o,u,s,L){return a(),e("div",null,[...l[0]||(l[0]=[t('<h1 id="_02-收拾行李-准备上路" tabindex="-1">02｜收拾行李，准备上路 <a class="header-anchor" href="#_02-收拾行李-准备上路" aria-label="Permalink to &quot;02｜收拾行李，准备上路&quot;">​</a></h1><p>你好，我是李锟。</p><p>我们即将踏上一段困难但充满惊喜的旅程。这段旅程意义重大，所以在出发之前，我们需要做好准备。以免因为仓促上路，没有携带必要的工具，导致半途而废。</p><p>首先我们需要掌握一些 LLM 应用开发的基础知识。对于部署在云端的商业 LLM，我们只需要学会其 API 和客户端库的使用方法即可。对于部署在本地机器上的开源 LLM，我们需要亲自来部署、调优。因此需要掌握的知识会多很多，但是这些努力的回报也会更大。</p><h2 id="llm-应用开发必备基础知识" tabindex="-1">LLM 应用开发必备基础知识 <a class="header-anchor" href="#llm-应用开发必备基础知识" aria-label="Permalink to &quot;LLM 应用开发必备基础知识&quot;">​</a></h2><p>首先我们需要理解与基础 LLM 相关的几个术语。</p><ul><li><p><strong>训练 training：</strong> 在训练数据集上构建复杂的模型，以捕捉更多的数据特征和模式，从而提高预测准确性。</p></li><li><p><strong>评估 evaluation：</strong> 对模型的性能进行定量和定性的评估，以确定模型的准确性和效率。</p></li><li><p><strong>微调 fine-tuning：</strong> 在预训练模型的基础上，使用少量数据进行精细调整，以适应特定任务的需求。</p></li><li><p><strong>部署 deployment：</strong> 将训练好的模型部署到生产环境中，以便实时处理用户请求或进行实时分析。</p></li><li><p><strong>推理 inference：</strong> 使用已训练好的模型进行预测或分类，以及解释模型输出的过程。</p></li></ul><p>大致理解了上述 5 个术语，我们可以把 LLM 开发划分成两个层次。</p><ol><li>基础 LLM 的研发</li></ol><ul><li><p>包括了训练、评估、微调、部署、推理所有 5 类工作。</p></li><li><p>成本高昂，需要万块高端显卡，耗时漫长。其中训练的成本最为高昂，只有投资上亿元的大公司才能负担得起。</p></li></ul><ol start="2"><li>基于基础 LLM 的应用开发</li></ol><ul><li><p>不包括训练、评估，仅包括微调（可选）、部署（可选）、推理。</p></li><li><p>因为不做训练，成本比训练小得多。仅做微调，成本只有训练的约千分之一。</p></li><li><p>如果微调也不做，成本比微调还要小得多，只有微调的约十分之一。</p><ul><li><p>使用普通消费级显卡即可，例如 Nvidia GeForce 系列的 RTX 3070、RTX 4090 等。</p></li><li><p>将训练好的模型进一步优化瘦身之后，甚至可以部署在嵌入设备内，例如树莓派、智能手机。</p></li></ul></li></ul><p>LLM 的诞生，特别是 <strong>OpenAI API</strong>（RESTful API + 客户端库）所确立的一套 LLM 应用开发的行业事实标准，彻底改变了传统 NLP（Natural Language Processing）应用开发的经济学。</p><p>开发传统的 NLP 应用时，开发者需要从底层基础语言模型开始开发，必须非常熟悉 CNN、RNN、Transformer 等各种 AI 算法和架构。同时还需要非常熟悉特定领域的业务需求，然后为该领域量身定制相应的语言模型。这样对开发者的技能要求非常之高，学习曲线非常陡峭。因此传统 NLP 应用的开发周期很长、成本很高。即使 NLP 应用开发完成，在上线之后的很长时间内，仍然需要投入很多人力来做手工标注，以改善 NLP 应用的准确性和性能。</p><p>所以在传统 NLP 行业有一句流行的话：“有多少人工，就有多少智能”。这句话确实很搞笑，也很无奈。我把传统 NLP 应用的开发模式称作“ <strong>气宗模式</strong>”（可参阅金庸小说《笑傲江湖》），因为按照华山派气宗的观点，在你没有多年练气获得深厚的内力之前，完全不应该练剑。</p><p>与之相对应，今天我们做 LLM 应用的开发，学习掌握大量基础 LLM 研发的知识并非是必要的。OpenAI API 实现了清晰的关注点分离，大幅降低 LLM 应用的开发成本，引爆了 LLM 应用开发的庞大市场。我把 LLM 应用的开发模式称作“ <strong>剑宗模式</strong>”，即使你只专心练剑，同样也可以成为武林高手，而且成效更快。以后如果你能同时练气，当然也会很有帮助。专业的事交给专业的人去做，随着各种基础 LLM 的迅速进步，更适于 <strong>大规模工业化</strong> 的剑宗开发模式未来必然会大行其道。</p><p>在做 LLM 应用开发时，我们用到的语言模型可以划分为两大类：</p><ol><li><strong>Chat 模型</strong></li></ol><ul><li><p>包括 LLM 和一些优化后的小模型，自带聊天（Chat）能力。</p></li><li><p>开源 Chat 模型举例（Hugging Face Hub 上的名称）</p><ul><li><p>meta-llama/Meta-Llama-3.2-8B</p></li><li><p>Qwen/Qwen2.5-7B-Instruct</p></li><li><p>THUDM/glm-4-9b-chat</p></li></ul></li></ul><ol start="2"><li><strong>Embedding 模型</strong></li></ol><ul><li><p>用来实现文本的向量化，即所谓的嵌入，用来实现知识库类应用。</p></li><li><p>开源 Embedding 模型举例（Hugging Face Hub 上的名称）</p><ul><li><p>BAAI/bge-large-zh-v1.5</p></li><li><p>nomic-ai/nomic-embed-text-v1.5</p></li></ul></li></ul><p>除了这两大类语言模型，还有一类不支持聊天，仅能做 <strong>文本补全</strong> 的模型，例如 OpenAI 早期发布的 text-davinci-003。不过单纯的文本补全模型现在用的已经很少了，因为 Chat 模型具有文本补全模型的所有功能。</p><p>接下来我们还需要理解一个非常重要的概念——模型的量化。</p><p>什么是量化（Quantization）？</p><p>量化在 AI 模型中，特别是在深度学习模型中，通常指的是将模型中的参数（例如权重和偏置）从浮点数转换为低位宽度的整数，例如从 32 位的浮点数转换为 8 位整数。</p><p>量化的优缺点是什么？</p><ul><li><p>优点：减少存储需求、加速计算、减少能耗。</p></li><li><p>缺点：会导致模型的精度下降。因为你实际上是在用较低的精度来表示原始的浮点数，可能会损失一些信息，这意味着模型的能力会变差。</p></li></ul><p>量化与语言模型文件的格式：</p><ul><li><p>不同的语言模型文件格式，对应着不同的量化方法。</p></li><li><p>模型文件名中的 fp32、fp16、int8、int4 字样表示模型的量化精度。fp32为全精度，量化精度从高到低排列顺序是：fp32&gt;fp16&gt;int8&gt;int4，量化的精度越低，模型的大小和推理所需的显存就越小，但模型的能力也会越差。</p></li></ul><h2 id="开源语言模型的发布平台和文件格式" tabindex="-1">开源语言模型的发布平台和文件格式 <a class="header-anchor" href="#开源语言模型的发布平台和文件格式" aria-label="Permalink to &quot;开源语言模型的发布平台和文件格式&quot;">​</a></h2><p>目前开源语言模型主要有以下几个发布平台：</p><ul><li><p>Hugging Face Hub： <a href="https://huggingface.co/" target="_blank" rel="noreferrer">https://huggingface.co</a></p></li><li><p>Ollama网站： <a href="https://ollama.com/" target="_blank" rel="noreferrer">https://ollama.com</a></p></li><li><p>ModelScope（国内）： <a href="https://www.modelscope.cn/home" target="_blank" rel="noreferrer">https://www.modelscope.cn/home</a></p></li></ul><p><strong>先介绍一下 Hugging Face Hub，这是世界最大的开源 AI 模型发布平台。</strong></p><p>Hugging Face Hub 是一个协作平台，其中托管了大量的用于机器学习的开源模型和数据集，可以将其视为 ML 的 GitHub。该平台让你可以轻松地找到、学习开源社区中有用的 ML 资产并与之交互，从而促进共享和协作。该平台已经与 Transformers 库（Hugging Face Transformers）深度集成，使用 Transformers 库部署的模型都是从该平台下载的。</p><p><strong>接下来我们了解一下 Ollama。</strong></p><p>Ollama 是一个开源的 LLM 服务，提供了类似 OpenAI 的 API 和聊天界面，可以非常方便地部署最新版本的 GPT 模型并通过 API 使用。支持热加载模型文件，无需重新启动即可切换不同的模型。Ollama 由 Meta 推出，系出名门，但不限于支持自家的 Llama 系列开源 LLM。底层代码基于著名的开源项目 llama.cpp，因此可完全跨平台（支持 Linux、macOS、Windows）。</p><p>Ollama 包括两个部分：</p><ul><li><p>Ollama 网站：类似 Hugging Face Hub，也是一个开源 LLM 的发布平台，规模远小于 Hugging Face Hub，且仅包括语言模型。</p></li><li><p>Ollama 工具：ollama 命令行工具；ollama daemon 服务，提供了与 OpenAI API 兼容的 Ollama API。</p></li></ul><p><strong>ModelScope 比较简单，可以简单理解为中国版的 Hugging Face Hub。</strong></p><p>从上述发布平台下载的开源语言模型文件有以下 5 种常见格式：</p><ol><li>Safetensors 格式</li></ol><ul><li><p>Hugging Face Hub 上最常见的模型格式。</p></li><li><p>Hugging Face 推出的一种可靠、易移植的机器学习模型存储格式，用于安全地存储 Tensor，而且速度很快（零拷贝）。</p></li></ul><ol start="2"><li>GPTQ 格式（Generalized Post-Training Quantization）</li></ol><ul><li><p>Hugging Face Hub 上常见的模型格式</p></li><li><p>GPTQ 是一种针对 4 位量化的训练后量化（PTQ）方法，主要关注GPU推理和性能。</p></li><li><p>该方法的思想是通过将所有权重压缩到4位量化中，通过最小化与该权重的均方误差来实现。在推理过程中，它将动态地将权重解量化为 float16，以提高性能，同时保持内存较低。</p></li></ul><ol start="3"><li>GGUF 格式（GPT-Generated Unified Format，前身叫 GGML）</li></ol><ul><li><p>Ollama 网站上大多数模型的格式。</p></li><li><p>由开发者Georgi Gerganov提出，是 <strong>专为大型语言模型设计</strong> 的二进制文件格式，旨在解决当前 LLM 在实际应用中遇到的存储效率、加载速度、兼容性和扩展性等问题。</p></li></ul><ol start="4"><li>AWQ 格式（Activation-aware Weight Quantization）</li></ol><ul><li>一种类似于GPTQ的量化方法。AWQ和GPTQ作为方法有几个不同之处，但最重要的是AWQ假设并非所有权重对LLM的性能都同等重要。也就是说在量化过程中会跳过一小部分权重，这有助于减轻量化损失。所以他们的论文提到了与GPTQ相比，AWQ可以有显著加速，同时保持了相似的、有时甚至更好的性能。</li></ul><ol start="5"><li>AQLM 格式（Additive Quantization of Language Models）</li></ol><ul><li><p>于2024年2月发布，已经集成到了 Hugging Face 中。</p></li><li><p>现有的仅权重量化算法在技术上可以将模型权重量化到2位范围。然而，它们未能有效地保持模型的准确性。AQLM是一种新的仅权重后训练量化（PTQ）算法，为2比特/每参数范围设定了新的技术水平。与现有方法相比，它还提供了更小的基准改进，适用于3位和4位范围。具体来说，AQLM 优于流行的算法如 GPTQ，以及更近期但较不知名的方法如 SpQR 和 QuIP。</p></li></ul><p>上述这 5 种文件格式不是固定的，随着开源语言模型的迅速发展，未来还会诞生新的文件格式。</p><p>了解了必备基础知识，那么在基于开源 LLM 做 LLM 应用开发之前，我们还需要准备一台适合的机器。</p><h2 id="准备开发机器和系统" tabindex="-1">准备开发机器和系统 <a class="header-anchor" href="#准备开发机器和系统" aria-label="Permalink to &quot;准备开发机器和系统&quot;">​</a></h2><p>你需要准备一台配置较高的 Linux 主机或虚拟机，可参考以下配置：</p><ul><li><p>内存：32G</p></li><li><p>CPU：酷睿 8 核 i7 以上</p></li><li><p>显卡：Nvidia GeForce RTX 3070 以上，至少 8G显存</p></li><li><p>操作系统：Ubuntu Linux 22.04 或 24.04，Server 版或 Desktop 版都可以</p></li></ul><p>如果不额外说明，本课程以后的所有操作均在 Linux 主机上执行。在 Windows 10 以上版本中，可以通过安装 WSL2 + Ubuntu 来使用 Linux，具体安装方法请查阅微软的官方文档。</p><p>在满足上述要求的 Linux 主机上，还需要安装好 Nvidia 的 CUDA 开发工具集。</p><p>CUDA（Compute Unified Device Architecture）是 Nvidia 推出的运算平台。是一种通用的并行计算架构，该架构使得 GPU 能够解决复杂的计算问题。</p><p>对于独立的 Linux 环境：</p><ul><li>安装 Nvidia 驱动程序 <ul><li>参考文档： <a href="https://ubuntu.com/server/docs/nvidia-drivers-installation" target="_blank" rel="noreferrer">https://ubuntu.com/server/docs/nvidia-drivers-installation</a></li></ul></li><li>安装与显卡型号和 Nvidia 驱动程序版本兼容的 CUDA 开发工具集 <ul><li><p>使用 nvidia-smi 命令获取 Nvidia 驱动程序的版本号</p></li><li><p><a href="https://docs.nvidia.com/deploy/cuda-compatibility" target="_blank" rel="noreferrer">https://docs.nvidia.com/deploy/cuda-compatibility</a> 查看 CUDA 版本与 Nvidia 驱动版本的兼容表。</p></li><li><p><a href="https://developer.nvidia.com/cuda-toolkit-archive" target="_blank" rel="noreferrer">https://developer.nvidia.com/cuda-toolkit-archive</a> 下载安装兼容版本的 CUDA 开发工具集，参考官方安装文档。</p></li></ul></li></ul><p>对于通过 Windows 的 WSL2 使用的 Linux 环境：</p><ul><li>在 WSL2 中启用 Nvidia CUDA <ul><li>参考文档： <a href="https://learn.microsoft.com/zh-cn/windows/ai/directml/gpu-cuda-in-wsl" target="_blank" rel="noreferrer">https://learn.microsoft.com/zh-cn/windows/ai/directml/gpu-cuda-in-wsl</a></li></ul></li></ul><p>接下来我们在 Linux 主机上部署一些开源 LLM。</p><h2 id="开源-llm-的部署工具——ollama" tabindex="-1">开源 LLM 的部署工具——Ollama <a class="header-anchor" href="#开源-llm-的部署工具——ollama" aria-label="Permalink to &quot;开源 LLM 的部署工具——Ollama&quot;">​</a></h2><p>开源语言模型的部署工具有很多，目前主流的有三个：</p><ul><li><p>Hugging Face Hub 命令行工具 huggingface-cli</p></li><li><p>Ollama</p></li><li><p>vLLM</p></li></ul><p>Hugging Face Hub 和 Ollama 前面已经做过介绍了，这里介绍一下 vLLM。</p><p>vLLM 是加州大学伯克利分校 LMSYS 组织开源的大语言模型高速推理框架。它利用了全新的注意力算法 “PagedAttention”，提供了易用、快速、便宜的 LLM 服务。项目地址： <a href="https://github.com/vllm-project/vllm" target="_blank" rel="noreferrer">https://github.com/vllm-project/vllm</a></p><p>vLLM 并没有自己的开源语言模型发布平台，它可以直接使用 Hugging Face Hub 或 Ollama 网站下载的开源语言模型，并且提供量化和加速支持。参考文档：</p><ul><li><p><a href="https://docs.vllm.ai/en/latest/getting_started/quickstart.html" target="_blank" rel="noreferrer">https://docs.vllm.ai/en/latest/getting_started/quickstart.html</a></p></li><li><p><a href="https://qwen.readthedocs.io/zh-cn/latest/deployment/vllm.html" target="_blank" rel="noreferrer">https://qwen.readthedocs.io/zh-cn/latest/deployment/vllm.html</a></p></li></ul><p>Hugging Face Hub 上的开源语言模型文件大多数都是 Safetensors 格式，基于 Hugging Face Transformers 库开发，依赖 PyTorch，因此需要配备很好的显卡才能流畅运行。上节课已经提到，我们希望开源 LLM 能够在硬件配置较低的机器上运行，那么 huggingface-cli 就无法满足我们的期望了。</p><p>Ollama 是基于 llama.cpp 的，即使没有安装 Nvidia 独立显卡，只要 CPU 足够强大，内存足够多，就能运行开源 LLM。而 vLLM 是基于 CUDA 库的，必须安装 Nvidia 独立显卡，对硬件配置的要求高于 Ollama。因此我们会优先选择使用 Ollama 来部署开源 LLM。从简化教学的角度，vLLM 我们就不做展开了，感兴趣的学员们可以自行学习。</p><p>Ollama 的基本用法如下。</p><ul><li>下载安装 Ollama： <ul><li><p>curl -fsSL <a href="https://ollama.com/install.sh" target="_blank" rel="noreferrer">https://ollama.com/install.sh</a> | sudo sh</p></li><li><p>验证 ollama 可运行：ollama --version</p></li></ul></li><li>Ollama 命令行工具的使用方法 <ul><li><p>ollama pull qwen2.5:7b  下载通义千问 Qwen2.5-7B</p></li><li><p>ollama run qwen2.5:7b  测试通义千问 Qwen2.5-7B</p></li><li><p>ollama rm qwen2.5:7b 删除通义千问 Qwen2.5-7B</p></li><li><p>ollama pull znbang/bge:large-zh-v1.5-f16 下载开源Embedding模型</p></li><li><p>ollama list 查看已下载的模型列表</p></li></ul></li></ul><p>在上面的 ollama 命令行工具的使用例子中，下载部署了开源 Chat 模型阿里巴巴 qwen2.5、Embedding 模型 bge:large-zh-v1.5-f16。在后续课程中，我们还会使用更多的开源语言模型。</p><h2 id="总结时刻" tabindex="-1">总结时刻 <a class="header-anchor" href="#总结时刻" aria-label="Permalink to &quot;总结时刻&quot;">​</a></h2><p>大多数 LLM 应用开发的图书、教程都只介绍了调用云端部署的商业 LLM 的 API。然而调用云端 LLM 的 API 有很多限制，除了会产生一些费用外，访问的频率、响应速度也有很多限制。</p><p>本课程中的实战环节将会以本地部署的开源 LLM 为主来开展教学，以避免上述问题。同时开源 LLM 也给了开发者极大的自由度，可以自由尝试各种奇思妙想。</p><p>既然决定基于开源 LLM 开展教学，我们就需要先学习掌握一些与开源 LLM 相关的基础知识和工具，以便顺利部署、使用开源 LLM，甚至以后对 LLM 做性能调优。我们优先选择的开源 LLM 部署工具是 Ollama，使用的开源 LLM 文件是来自 Ollama 网站的 GGUF 格式的文件。</p><p>在选择了 Ollama 之后，我们优先选择的开源 LLM 是由阿里巴巴开发的 qwen-2.5，也是目前最为强大的国产开源 LLM。当然，优秀的开源 LLM 还有不少，后续我们会根据教学需要，引入其他开源 LLM。本课程中的代码，稍作修改，同样可以使用云端商业 LLM，例如 OpenAI 的 GPT-4o 或者阿里巴巴的通义千问。</p><p>下节课我们将进入实战环节，开始学习第一个 Autonomous Agent 开发框架——MetaGPT 的基础知识。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>开发 LLM 应用有哪些自己的关注点，与做基础 LLM 研发的关注点有何区别？为何我们必须做关注点分离？</p></li><li><p>开源语言模型有哪些文件格式？它们各自有何特点？</p></li></ol><p>期待你的分享。如果今天的内容对你有所帮助，也期待你转发给你的同事或者朋友，大家一起学习，共同进步。我们下节课再见！</p>',84)])])}const c=i(p,[["render",n]]);export{m as __pageData,c as default};
